'use client';

import { useId, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { AlertTriangle, ArrowDownLeft, ArrowRight, ArrowRightLeft, ArrowUpRight, Banknote, CalendarCheck2, Check, CheckCheck, ChevronRight, ClipboardCheck, Coins, ExternalLink, FileCheck2, FileText, History, Landmark, Link2, LockKeyhole, Paperclip, Plus, Search, ShieldCheck, Wallet } from 'lucide-react';
import { add, formatCOP, fromCents, getAccountBalance, money, sub, toCents, todayBogota, type Account, type State, type Support, type Transaction } from '@/lib/finance';
import {
  CASH_DENOMINATIONS,
  attachCashSupport, cashMonthChecklist, closeCashMonth, closeCashSession, getCashSessionSummary, getCashState,
  getCashTransactionMetadata, legalizeAdvance, openCashSession, recordCashCount, recordCashTransferReceipt,
  registerCashMovement, requestCashAmendment,
} from '@/lib/finance/cash';
import { CASH_OUTFLOW_GROUPS, CASH_INFLOW_CATEGORIES } from '@/lib/finance/cash-catalog';
import type { CashCountDenomination, CashMovementInput, CashSession } from '@/lib/finance/cash-types';
import { Badge, Field, Modal } from './ui';
import { accountKindLabels, canWrite, dateLabel, kindLabels, timestamp, type ViewProps } from './view-helpers';

type CashViewProps = ViewProps & { onConfigureAccounts?:()=>void };
type CashTab = 'sessions'|'movements'|'month';
type CashDialog = {kind:'open'}|{kind:'count';sessionId:string}|{kind:'close';sessionId:string}|{kind:'movement';sessionId?:string}|{kind:'support';transactionId:string}|{kind:'legalize';transactionId:string}|{kind:'correct';transactionId:string}|{kind:'receipt';transactionId:string}|{kind:'history';sessionId:string}|{kind:'month';month:string};
const normalizeAmount=(value:string)=>value.trim().replace(',','.');
const explanation=(reason:unknown)=>reason instanceof Error?reason.message:'No fue posible completar la operación. Revisa los campos.';
const monthName=(month:string)=>new Intl.DateTimeFormat('es-CO',{month:'long',year:'numeric',timeZone:'America/Bogota'}).format(new Date(`${month}-01T12:00:00Z`));
const moneyOrDash=(value:string|null|undefined)=>value===null||value===undefined?'—':formatCOP(value);

function usableAccounts({state,actor,location}:ViewProps):Account[] {
  const member=state.members.find(row=>row.id===actor.id&&row.active);
  return state.accounts.filter(account=>account.kind!=='ledger'&&account.active&&(location==='all'||account.locationId===location)&&Boolean(member?.locationIds.includes(account.locationId)));
}
function safeHttps(value:string|undefined):string|undefined {
  if(!value?.trim())return undefined;
  const url=new URL(value.trim());
  if(url.protocol!=='https:'||url.username||url.password)throw new Error('El comprobante debe usar un enlace HTTPS sin credenciales.');
  return url.href;
}
function displaySupportUrl(value:string|undefined):string|undefined {try{return safeHttps(value);}catch{return undefined;}}
function displaySupportData(support:Support|undefined):string|undefined {
  if(!support?.dataUrl||!['application/pdf','image/png','image/jpeg','image/webp'].includes(support.type)||!Number.isSafeInteger(support.size)||support.size<=0||support.size>5*1024*1024)return undefined;
  const prefix=`data:${support.type};base64,`;if(!support.dataUrl.startsWith(prefix)||support.dataUrl.length>7*1024*1024)return undefined;
  const encoded=support.dataUrl.slice(prefix.length);if(!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(encoded))return undefined;
  const size=encoded.length/4*3-(encoded.endsWith('==')?2:encoded.endsWith('=')?1:0);
  return size===support.size?support.dataUrl:undefined;
}
function transactionAccountNames(state:State,transaction:Transaction):string {
  if(transaction.kind==='transfer')return [sourceAccount(state,transaction)?.name,accountDestination(state,transaction)?.name].filter(Boolean).join(' → ');
  return transaction.entries.flatMap(entry=>{const account=state.accounts.find(row=>row.id===entry.accountId);return account&&account.kind!=='ledger'?[account.name]:[];}).join(' → ');
}
function sourceAccount(state:State,transaction:Transaction):Account|undefined {
  const entry=transaction.entries.find(row=>toCents(row.credit)>0n&&state.accounts.some(account=>account.id===row.accountId&&account.kind!=='ledger'));
  return state.accounts.find(row=>row.id===entry?.accountId);
}
function accountDestination(state:State,transaction:Transaction):Account|undefined {
  const entry=transaction.entries.find(row=>toCents(row.debit)>0n&&state.accounts.some(account=>account.id===row.accountId&&account.kind!=='ledger'));
  return state.accounts.find(row=>row.id===entry?.accountId);
}

export function CashView(props:CashViewProps) {
  const {state,actor,location,mutate}=props;
  const [tab,setTab]=useState<CashTab>('sessions');
  const [dialog,setDialog]=useState<CashDialog|null>(null);
  const tabPrefix=useId();
  const cash=getCashState(state);
  const accounts=usableAccounts(props);
  const cashAccounts=accounts.filter(account=>account.kind==='cash');
  const accountIds=new Set(accounts.map(account=>account.id));
  const sessions=cash.sessions.filter(session=>accountIds.has(session.accountId)).sort((a,b)=>b.openedAt.localeCompare(a.openedAt));
  const openSessions=sessions.filter(session=>session.status==='open');
  const pendingLegalizations=cash.legalizations.filter(row=>row.status!=='documented'&&state.transactions.some(transaction=>transaction.id===row.transactionId&&(location==='all'||transaction.locationId===location)&&transaction.status!=='rejected'));
  const requests=cash.amendmentRequests.filter(request=>request.status==='pending_institutional'&&(!request.transactionId||state.transactions.some(transaction=>transaction.id===request.transactionId&&(location==='all'||transaction.locationId===location))));
  const selectedSession=dialog&&'sessionId'in dialog?cash.sessions.find(session=>session.id===dialog.sessionId):undefined;
  const selectedTransaction=dialog&&'transactionId'in dialog?state.transactions.find(transaction=>transaction.id===dialog.transactionId):undefined;
  return <div className="cash-workspace">
    <div className="cash-navigation" role="tablist" aria-label="Manejo de caja">
      {([{id:'sessions',label:'Turnos y arqueos',icon:Banknote},{id:'movements',label:'Movimientos y legalización',icon:ArrowRightLeft},{id:'month',label:'Cierre mensual',icon:CalendarCheck2}] as const).map(({id,label,icon:Icon},index)=><button key={id} id={`${tabPrefix}-${id}`} type="button" role="tab" aria-selected={tab===id} aria-controls={`${tabPrefix}-panel`} tabIndex={tab===id?0:-1} onClick={()=>setTab(id)} onKeyDown={event=>{const ordered:CashTab[]=['sessions','movements','month'];let next:number|undefined;if(event.key==='ArrowRight')next=(index+1)%ordered.length;else if(event.key==='ArrowLeft')next=(index+ordered.length-1)%ordered.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=ordered.length-1;if(next!==undefined){event.preventDefault();setTab(ordered[next]);event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>('[role="tab"]')[next]?.focus();}}}><Icon size={17}/>{label}</button>)}
    </div>
    <div className="cash-info"><ShieldCheck size={17}/><span>Libro local de Trefil Electric. Los registros de esta sección se conservan en este navegador. Las solicitudes de corrección y cierre excepcional quedan pendientes de autorización institucional; no se simulan códigos ni aprobaciones.</span></div>
    <div className="cash-tab-panel" role="tabpanel" id={`${tabPrefix}-panel`} aria-labelledby={`${tabPrefix}-${tab}`}>
    {tab==='sessions'&&<>
      <div className="cash-toolbar"><div><h2>Control de efectivo, desde la apertura hasta el cierre</h2><p>El turno toma su saldo del libro. Un arqueo documenta el dinero contado y conserva cualquier diferencia.</p></div><div className="cash-actions">{canWrite(actor)&&<button className="button button-primary" disabled={!cashAccounts.length} onClick={()=>setDialog({kind:'open'})}><Plus size={16}/>Abrir turno</button>}</div></div>
      <div className="cash-summary">
        <Metric title="Efectivo en libros" value={formatCOP(add(...cashAccounts.map(account=>getAccountBalance(state,account.id))))} note={`${cashAccounts.length} ${cashAccounts.length===1?'caja de efectivo':'cajas de efectivo'}`} featured/>
        <Metric title="Turnos abiertos" value={String(openSessions.length)} note="Con responsable y apertura registrada"/>
        <Metric title="Por legalizar" value={String(pendingLegalizations.length)} note="Soportes o clasificación pendientes"/>
        <Metric title="Solicitudes pendientes" value={String(requests.length)} note="Requieren autorización institucional"/>
      </div>
      {!cashAccounts.length?<CashEmpty title="Primero configura tu caja de efectivo" description="No hay cajas de tipo Efectivo en esta sede. Créala en Cuentas, asigna su responsable y luego abre el primer turno. Empezará con saldo cero; una apertura de turno no crea dinero." action={props.onConfigureAccounts?<button className="button button-primary" onClick={props.onConfigureAccounts}><Wallet size={16}/>Configurar cuentas</button>:undefined}/>:!sessions.length?<CashEmpty title="La caja está lista para su primer turno" description="Selecciona una caja y registra la apertura. El sistema conservará la fecha, la persona responsable y el saldo calculado desde los movimientos." action={canWrite(actor)?<button className="button button-primary" onClick={()=>setDialog({kind:'open'})}><Plus size={16}/>Abrir primer turno</button>:undefined}/>:<>
        {openSessions.length>0&&<div className="cash-session-grid">{openSessions.map(session=>{
          const account=state.accounts.find(row=>row.id===session.accountId)!;
          const summary=getCashSessionSummary(state,session.id);
          return <section className="cash-session-card" key={session.id}>
            <div className="cash-session-top"><span className="cash-account-symbol"><Banknote size={21}/></span><div><h3>{account.name}</h3><p>{dateLabel(session.date)} · {session.openedByName}</p></div><Badge tone="blue">Turno abierto</Badge></div>
            <div className="cash-session-balances"><div><small>Saldo teórico actual</small><strong>{formatCOP(summary.theoreticalBalance)}</strong></div><div><small>Último arqueo contado</small><strong>{moneyOrDash(summary.countedAmount)}</strong></div></div>
            <div className="cash-session-activity"><span>Apertura: <b>{formatCOP(summary.openingBalance)}</b></span><span>Entradas: <b>{formatCOP(summary.inflows)}</b></span><span>Salidas: <b>{formatCOP(summary.outflows)}</b></span></div>
            {summary.difference!==null&&toCents(summary.difference)!==0n&&<div className="cash-warning" style={{marginTop:16}}><AlertTriangle size={17}/><p><strong>{toCents(summary.difference)<0n?'Faltante pendiente':'Sobrante pendiente de legalizar'}: {formatCOP(summary.difference)}</strong><br/>El arqueo conserva la diferencia y no ajusta los saldos automáticamente.</p></div>}
            <div className="cash-session-footer"><button className="cash-text-button" onClick={()=>setDialog({kind:'history',sessionId:session.id})}><History size={14}/>Ver historial</button><div className="cash-actions">{canWrite(actor)&&<><button className="button button-secondary" onClick={()=>setDialog({kind:'count',sessionId:session.id})}><Coins size={15}/>Arqueo</button><button className="button button-primary" onClick={()=>setDialog({kind:'close',sessionId:session.id})}><LockKeyhole size={15}/>Cerrar turno</button></>}</div></div>
          </section>;
        })}</div>}
        <section className="cash-card"><div className="cash-card-header"><div><h3>Historial de turnos</h3><p>Las aperturas, arqueos y cierres se conservan. Un cierre excepcional solicitado no cierra el turno.</p></div><Badge>{sessions.length} turnos</Badge></div><div className="cash-table-wrap"><table className="cash-table"><thead><tr><th>Caja y fecha</th><th>Responsable</th><th>Apertura en libros</th><th>Último arqueo</th><th>Estado</th><th>Consulta</th></tr></thead><tbody>{sessions.map(session=>{
          const summary=getCashSessionSummary(state,session.id);
          return <tr key={session.id}><td><strong>{state.accounts.find(account=>account.id===session.accountId)?.name}</strong><small>{dateLabel(session.date)} · {timestamp(session.openedAt)}</small></td><td>{session.openedByName}</td><td className="cash-money">{formatCOP(session.openingBalance)}</td><td className="cash-money">{moneyOrDash(summary.countedAmount)}</td><td><Badge tone={session.status==='open'?'blue':'green'}>{session.status==='open'?'Abierto':'Cerrado localmente'}</Badge></td><td><button className="cash-text-button" onClick={()=>setDialog({kind:'history',sessionId:session.id})}>Ver detalle <ChevronRight size={15}/></button></td></tr>;
        })}</tbody></table></div></section>
      </>}
    </>}
    {tab==='movements'&&<CashMovements {...props} accounts={accounts} onDialog={setDialog}/>}
    {tab==='month'&&<CashMonth {...props} onCloseMonth={month=>setDialog({kind:'month',month})}/>}
    </div>
    {dialog?.kind==='open'&&<OpenSessionModal {...props} accounts={cashAccounts} onClose={()=>setDialog(null)}/>}
    {(dialog?.kind==='count'||dialog?.kind==='close')&&selectedSession&&<CountModal {...props} session={selectedSession} closing={dialog.kind==='close'} onClose={()=>setDialog(null)}/>}
    {dialog?.kind==='movement'&&<CashMovementModal {...props} accounts={accounts} initialSessionId={dialog.sessionId} onClose={()=>setDialog(null)}/>}
    {dialog?.kind==='history'&&selectedSession&&<SessionHistory state={state} session={selectedSession} onClose={()=>setDialog(null)}/>}
    {(dialog?.kind==='support'||dialog?.kind==='legalize'||dialog?.kind==='correct')&&selectedTransaction&&<MovementEvidenceModal {...props} mode={dialog.kind} transaction={selectedTransaction} onClose={()=>setDialog(null)}/>}
    {dialog?.kind==='receipt'&&selectedTransaction&&<TransferReceiptModal {...props} transaction={selectedTransaction} onClose={()=>setDialog(null)}/>}
    {dialog?.kind==='month'&&<MonthCloseModal {...props} month={dialog.month} onClose={()=>setDialog(null)}/>}
    <p className="cash-page-caption">Los importes conservan centavos exactos en COP. Un guion indica que falta información; no equivale a un importe cero. Los movimientos rechazados y las solicitudes pendientes nunca modifican los saldos.</p>
  </div>;
}

function Metric({title,value,note,featured=false}:{title:string;value:string;note:string;featured?:boolean}){return <div className={`cash-summary-card ${featured?'cash-summary-featured':''}`}><span>{title}</span><strong>{value}</strong><small>{note}</small></div>;}
function CashEmpty({title,description,action}:{title:string;description:string;action?:ReactNode}){return <div className="cash-empty"><span><Wallet size={24}/></span><h3>{title}</h3><p>{description}</p>{action}</div>;}

function OpenSessionModal({state,actor,mutate,accounts,onClose}:ViewProps&{accounts:Account[];onClose:()=>void}) {
  const [accountId,setAccountId]=useState('');
  const [notes,setNotes]=useState('');
  const [error,setError]=useState('');
  const date=todayBogota();const account=accounts.find(row=>row.id===accountId);
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setError('');try{if(mutate(current=>openCashSession(current,{accountId,date,notes},actor),'Turno abierto en el libro local. No se creó un saldo adicional.'))onClose();}catch(reason){setError(explanation(reason));}}
  return <Modal title="Abrir turno de efectivo" subtitle="La apertura registra la custodia del dinero existente; no genera un ingreso." onClose={onClose}><form className="cash-dialog" onSubmit={submit}>
    <div className="form-grid"><Field label="Caja de efectivo" full><select value={accountId} required onChange={event=>setAccountId(event.target.value)}><option value="" disabled>Selecciona la caja</option>{accounts.map(row=><option key={row.id} value={row.id}>{row.name}</option>)}</select></Field><Field label="Fecha de apertura"><input type="date" readOnly value={date}/></Field><Field label="Responsable de este turno"><input readOnly value={actor.name}/></Field><Field label="Saldo inicial calculado desde el libro" full hint="Para registrar dinero inicial usa un asiento de apertura aprobado; este valor no puede editarse aquí."><input readOnly value={account?formatCOP(getAccountBalance(state,accountId)):'Sin caja seleccionada'}/></Field><Field label="Observaciones de apertura" full><textarea value={notes} onChange={event=>setNotes(event.target.value)} maxLength={2000} rows={3} placeholder="Estado de entrega, referencia o novedad relevante…"/></Field></div>
    <div className="cash-info"><LockKeyhole size={17}/><p>No se permite una segunda apertura mientras el turno anterior de esta caja siga abierto. {actor.name} identifica la operación local y todavía no equivale a una sesión institucional.</p></div>
    {error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Cancelar</button><button type="submit" className="button button-primary" disabled={!accountId}>Abrir turno</button></div>
  </form></Modal>;
}

function CountModal({state,actor,mutate,session,closing,onClose}:ViewProps&{session:CashSession;closing:boolean;onClose:()=>void}) {
  const [quantities,setQuantities]=useState<Record<string,string>>({});
  const [notes,setNotes]=useState('');const [reason,setReason]=useState('');const [requesting,setRequesting]=useState(false);const [savedCount,setSavedCount]=useState(false);const [error,setError]=useState('');
  const labelId=useId();const summary=getCashSessionSummary(state,session.id);
  const account=state.accounts.find(row=>row.id===session.accountId)!;
  const complete=CASH_DENOMINATIONS.every(row=>/^\d+$/.test(quantities[row.id]??'')&&Number.isSafeInteger(Number(quantities[row.id]))&&Number(quantities[row.id])<=100000000);
  let counted:string|null=null;try{if(complete)counted=fromCents(CASH_DENOMINATIONS.reduce((total,row)=>total+toCents(row.value)*BigInt(quantities[row.id]),0n));}catch{/* Display a missing value until a valid count is supplied. */}
  const difference=counted===null?null:sub(counted,summary.theoreticalBalance);
  function denominations():CashCountDenomination[]{if(!complete||counted===null)throw new Error('Cuenta cada denominación. Escribe cero solo cuando hayas confirmado que no hay unidades.');return CASH_DENOMINATIONS.map(row=>({kind:row.kind,value:row.value,quantity:Number(quantities[row.id])}));}
  function saveCount(){setError('');try{if(mutate(current=>recordCashCount(current,{sessionId:session.id,denominations:denominations(),notes},actor),'Arqueo conservado. El turno sigue abierto y las diferencias no se ajustaron.'))setSavedCount(true);}catch(reason){setError(explanation(reason));}}
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setError('');try{
    const rows=denominations();
    const saved=requesting?mutate(current=>requestCashAmendment(recordCashCount(current,{sessionId:session.id,denominations:rows,notes},actor),{sessionId:session.id,kind:'exceptional_close',reason},actor),'Arqueo conservado y cierre excepcional solicitado. El turno permanece abierto hasta una autorización institucional.'):closing?mutate(current=>closeCashSession(current,{sessionId:session.id,denominations:rows,notes},actor),'Turno cerrado localmente. Se conservaron el arqueo y sus movimientos.'):mutate(current=>recordCashCount(current,{sessionId:session.id,denominations:rows,notes},actor),'Arqueo registrado. Los saldos originales se conservaron.');
    if(saved)onClose();
  }catch(reason){setError(explanation(reason));}}
  return <Modal title={closing?'Arqueo y cierre de turno':'Registrar arqueo de efectivo'} subtitle={`${account.name} · Turno del ${dateLabel(session.date)}`} onClose={onClose} wide><form className="cash-dialog" onSubmit={submit}>
    <div className="cash-info"><Coins size={18}/><p>Registra las unidades físicamente contadas. Las casillas empiezan vacías: «sin contar» es distinto de cero. El billete de $ 1.000 y la moneda de $ 1.000 se cuentan por separado.</p></div>
    <div className="cash-count-grid">{(['bill','coin'] as const).map(kind=><section className="cash-count-panel" key={kind}><h3>{kind==='bill'?<Banknote size={17}/>:<Coins size={17}/>} {kind==='bill'?'Billetes':'Monedas'}</h3>{CASH_DENOMINATIONS.filter(row=>row.kind===kind).map(row=>{
      const raw=quantities[row.id]??'';let line:string|undefined;try{if(/^\d+$/.test(raw)&&Number(raw)<=100000000)line=fromCents(toCents(row.value)*BigInt(raw));}catch{/* Invalid count remains absent. */}
      return <div className="cash-denomination-row" key={row.id}><span id={`${labelId}-${row.id}`}>{formatCOP(row.value)}</span><input type="number" min="0" max="100000000" step="1" inputMode="numeric" required value={raw} onChange={event=>{setSavedCount(false);setQuantities(previous=>({...previous,[row.id]:event.target.value}));}} aria-label={`${kind==='bill'?'Cantidad de billetes':'Cantidad de monedas'} de ${formatCOP(row.value)}`} aria-describedby={`${labelId}-${row.id}`} placeholder="—"/><small>{line===undefined?'Sin contar':formatCOP(line)}</small></div>;
    })}</section>)}</div>
    <div className="cash-count-result"><div><small>Saldo teórico</small><strong>{formatCOP(summary.theoreticalBalance)}</strong></div><div><small>Efectivo contado</small><strong>{moneyOrDash(counted)}</strong></div><div><small>{difference===null?'Diferencia':toCents(difference)<0n?'Faltante':toCents(difference)>0n?'Sobrante':'Diferencia'}</small><strong className={difference!==null&&toCents(difference)<0n?'cash-negative':difference==='0.00'?'cash-positive':''}>{moneyOrDash(difference)}</strong></div><p>Un faltante o sobrante queda como novedad. Guardar el arqueo nunca modifica dinero ni fabrica un ajuste.</p></div>
    <Field label="Observaciones y evidencia del conteo" full><textarea value={notes} onChange={event=>{setNotes(event.target.value);setSavedCount(false);}} maxLength={2000} rows={3} placeholder="Explica cualquier diferencia y cómo se verificó el efectivo…"/></Field>
    {savedCount&&<div className="cash-info" role="status"><CheckCheck size={17}/><p>Este arqueo ya está conservado. El turno sigue abierto; si un intento de cierre se rechaza, el conteo y su novedad permanecen en el historial.</p></div>}
    {closing&&difference!==null&&toCents(difference)!==0n&&<div className="cash-warning"><AlertTriangle size={18}/><p>Este turno tiene una diferencia y no puede cerrarse de forma ordinaria. La solicitud excepcional conserva la novedad abierta y no equivale a una aprobación.</p></div>}
    {closing&&summary.pendingTransactionIds.length>0&&<div className="cash-warning"><ClockIcon/><p>Hay {summary.pendingTransactionIds.length} movimientos pendientes de decisión. Revísalos antes de cerrar; todavía no afectan el saldo.</p></div>}
    {requesting&&<><div className="cash-info"><LockKeyhole size={17}/><p>Esta petición quedará pendiente de autorización institucional de Creador o Gerente. Aquí no se acepta un código compartido ni se suplanta a otra persona.</p></div><Field label="Motivo del cierre excepcional solicitado" full><textarea required minLength={8} maxLength={2000} rows={3} value={reason} onChange={event=>setReason(event.target.value)} placeholder="Explica por qué se solicita la excepción y qué novedad debe permanecer abierta…"/></Field></>}
    {error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Cancelar</button>{closing&&<><button type="button" className="button button-secondary" disabled={!complete||counted===null} onClick={saveCount}>Guardar arqueo sin cerrar</button><button type="button" className="button button-secondary" onClick={()=>setRequesting(value=>!value)}>{requesting?'Volver al cierre ordinario':'Solicitar cierre excepcional'}</button></>}<button type="submit" className="button button-primary" disabled={!complete||counted===null||Boolean(closing&&!requesting&&(difference!=='0.00'||summary.pendingTransactionIds.length>0))}>{requesting?'Guardar arqueo y solicitar excepción':closing?'Confirmar cierre ordinario':'Guardar arqueo'}</button></div>
  </form></Modal>;
}
function ClockIcon(){return <History size={17}/>;}

function SessionHistory({state,session,onClose}:{state:State;session:CashSession;onClose:()=>void}) {
  const cash=getCashState(state);const summary=getCashSessionSummary(state,session.id);
  const counts=cash.counts.filter(row=>row.sessionId===session.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const requests=cash.amendmentRequests.filter(row=>row.sessionId===session.id);
  return <Modal title={state.accounts.find(row=>row.id===session.accountId)?.name??'Detalle del turno'} subtitle={`Turno del ${dateLabel(session.date)} · ${session.status==='open'?'Abierto':'Cerrado localmente'}`} onClose={onClose} wide><div className="cash-dialog">
    <div className="cash-detail-block"><dl><div><dt>Responsable de apertura</dt><dd>{session.openedByName}</dd></div><div><dt>Fecha y hora de apertura</dt><dd>{timestamp(session.openedAt)}</dd></div><div><dt>Saldo de apertura</dt><dd>{formatCOP(session.openingBalance)}</dd></div><div><dt>Saldo teórico actual</dt><dd>{formatCOP(summary.theoreticalBalance)}</dd></div><div><dt>Cierre</dt><dd>{session.closedAt?timestamp(session.closedAt):'Todavía abierto'}</dd></div><div><dt>Observaciones iniciales</dt><dd>{session.notes||'Sin observaciones registradas'}</dd></div></dl></div>
    <h3>Arqueos conservados</h3>{counts.length?<div className="cash-history-list">{counts.map(count=><article key={count.id} className="cash-history-event"><div><strong>{count.purpose==='opening'?'Arqueo de apertura':count.purpose==='closing'?'Arqueo de cierre':'Arqueo de control'}</strong><Badge tone={toCents(count.difference)===0n?'green':toCents(count.difference)<0n?'red':'orange'}>{toCents(count.difference)===0n?'Sin diferencia':toCents(count.difference)<0n?'Faltante':'Sobrante'}</Badge></div><small>{count.actorName} · {timestamp(count.createdAt)}</small><p>Contado <b>{formatCOP(count.countedAmount)}</b> · Teórico {formatCOP(count.theoreticalBalance)} · Diferencia <b>{formatCOP(count.difference)}</b></p>{count.notes&&<p>{count.notes}</p>}<details><summary className="cash-text-button">Ver denominaciones contadas</summary><div className="cash-table-wrap"><table className="cash-table"><thead><tr><th>Tipo</th><th>Denominación</th><th>Unidades</th><th>Total contado</th></tr></thead><tbody>{count.denominations.map(row=><tr key={row.kind+row.value}><td>{row.kind==='bill'?'Billete':'Moneda'}</td><td>{formatCOP(row.value)}</td><td>{row.quantity}</td><td>{formatCOP(fromCents(toCents(row.value)*BigInt(row.quantity)))}</td></tr>)}</tbody></table></div></details></article>)}</div>:<div className="cash-info"><Coins size={17}/><p>Este turno todavía no tiene un arqueo registrado. No se asume que el efectivo contado sea cero.</p></div>}
    {requests.length>0&&<><h3>Solicitudes de cierre excepcional</h3><div className="cash-history-list">{requests.map(request=><article className="cash-history-event" key={request.id}><div><strong>Pendiente de autorización institucional</strong><Badge tone="orange">Sin aplicar</Badge></div><small>{request.requestedByName} · {timestamp(request.createdAt)}</small><p>{request.reason}</p></article>)}</div></>}
    <div className="modal-actions"><button className="button button-primary" onClick={onClose}>Cerrar detalle</button></div>
  </div></Modal>;
}

function CashMovements(props:CashViewProps&{accounts:Account[];onDialog:(dialog:CashDialog)=>void}) {
  const {state,actor,location,accounts,onDialog}=props;
  const today=todayBogota();const [start,setStart]=useState(today.slice(0,7)+'-01');const [end,setEnd]=useState(today);const [search,setSearch]=useState('');const [accountFilter,setAccountFilter]=useState('all');const [showAllQueue,setShowAllQueue]=useState(false);
  const cash=getCashState(state);const accountIds=new Set(accounts.map(account=>account.id));
  const rows=state.transactions.filter(transaction=>(location==='all'||transaction.locationId===location)&&transaction.date>=start&&transaction.date<=end&&transaction.entries.some(entry=>accountIds.has(entry.accountId))&&(accountFilter==='all'||transaction.entries.some(entry=>entry.accountId===accountFilter))&&`${transaction.description} ${transaction.party} ${transaction.reference}`.toLocaleLowerCase('es-CO').includes(search.toLocaleLowerCase('es-CO'))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));
  const operational=state.transactions.filter(transaction=>transaction.status==='posted'&&!transaction.reversalOf&&!transaction.reversedBy&&transaction.kind!=='opening'&&(location==='all'||transaction.locationId===location)&&transaction.entries.some(entry=>accountIds.has(entry.accountId)));
  const queue=operational.flatMap<{transaction:Transaction;kind:'legalize'|'support';title:string;description:string}>(transaction=>{
    const meta=getCashTransactionMetadata(state,transaction.id);
    const pending=cash.legalizations.find(row=>row.transactionId===transaction.id&&row.reason==='temporary_category'&&row.status!=='documented');
    if(pending)return [{transaction,kind:'legalize' as const,title:'Anticipo pendiente de legalización',description:pending.status==='pending_institutional'?'Clasificación solicitada; falta autorización institucional.':'Adjunta el comprobante y solicita su clasificación definitiva.'}];
    if(transaction.kind==='transfer'&&accountDestination(state,transaction)?.kind==='cash'&&sourceAccount(state,transaction)?.kind!=='cash'&&![meta?.support,transaction.support,...(meta.attachments??[]).map(row=>row.support)].some(support=>support?.type.startsWith('image/')&&Boolean(displaySupportData(support))))return [{transaction,kind:'support' as const,title:'Fotografía del retiro pendiente',description:'Un enlace o un PDF no verifica la fotografía exigida para el retiro hacia efectivo.'}];
    if(!meta?.support&&!displaySupportUrl(meta?.supportUrl)&&!transaction.support)return [{transaction,kind:'support' as const,title:'Comprobante pendiente',description:'Anexa el soporte desde esta ficha, aunque la operación corresponda a otro mes.'}];
    return [];
  });
  const requests=cash.amendmentRequests.filter(request=>request.transactionId&&operational.some(transaction=>transaction.id===request.transactionId));
  return <>
    <div className="cash-toolbar"><div><h2>Cada entrada y salida, con su propósito</h2><p>Registra efectivo desde un turno abierto. Los bancos y las pasarelas operan directamente en su propia cuenta.</p></div>{canWrite(actor)&&<button className="button button-primary" disabled={!accounts.length} onClick={()=>onDialog({kind:'movement'})}><Plus size={16}/>Registrar movimiento</button>}</div>
    {!accounts.length?<CashEmpty title="Configura las cuentas que vas a utilizar" description="Las cuentas de efectivo, banco y pasarela empiezan sin movimientos ni importes precargados. Una pasarela puede pagar directamente a un proveedor sin pasar por efectivo." action={props.onConfigureAccounts?<button className="button button-primary" onClick={props.onConfigureAccounts}><Wallet size={16}/>Ir a Cuentas</button>:undefined}/>:<>
      {queue.length>0&&<section className="cash-card"><div className="cash-card-header"><div><h3>Comprobantes y legalizaciones por resolver</h3><p>Abre la novedad para adjuntar evidencia o proponer una clasificación. El importe original no se sobrescribe.</p></div><Badge tone="orange">{queue.length} pendientes</Badge></div><div className="cash-card-body"><div className="cash-queue">{(showAllQueue?queue:queue.slice(0,6)).map(({transaction,kind,title,description})=><button key={transaction.id} className="cash-queue-item" onClick={()=>onDialog({kind,transactionId:transaction.id})}><AlertTriangle size={18}/><span><strong>{title}</strong><small>{transaction.description} · {dateLabel(transaction.date,true)}<br/>{description}</small></span><span className="cash-queue-amount">{formatCOP(transaction.amount)}</span></button>)}</div>{queue.length>6&&<button className="cash-text-button" onClick={()=>setShowAllQueue(value=>!value)} style={{marginTop:12}}>{showAllQueue?'Mostrar menos novedades':`Ver las ${queue.length} novedades`} <ChevronRight size={15}/></button>}</div></section>}
      <div className="cash-filters"><label>Desde<input type="date" value={start} max={end||today} onChange={event=>setStart(event.target.value)}/></label><label>Hasta<input type="date" value={end} min={start||undefined} max={today} onChange={event=>setEnd(event.target.value)}/></label><label>Cuenta<select value={accountFilter} onChange={event=>setAccountFilter(event.target.value)}><option value="all">Todas las cuentas</option>{accounts.map(account=><option key={account.id} value={account.id}>{account.name}</option>)}</select></label><label className="cash-search">Buscar movimiento<span><Search size={16}/><input type="search" value={search} placeholder="Concepto, tercero o referencia" onChange={event=>setSearch(event.target.value)}/></span></label></div>
      {rows.length?<section className="cash-card"><div className="cash-table-wrap"><table className="cash-table"><thead><tr><th>Concepto / fecha</th><th>Cuenta y tercero</th><th>Clasificación</th><th>Valor</th><th>Estado</th><th>Soporte y seguimiento</th></tr></thead><tbody>{rows.map(transaction=>{
        const meta=getCashTransactionMetadata(state,transaction.id);const receipt=cash.transferReceipts.find(row=>row.transactionId===transaction.id);const pending=cash.legalizations.find(row=>row.transactionId===transaction.id&&row.reason==='temporary_category'&&row.status!=='documented');
        const support=meta?.support??transaction.support;const fileUrl=displaySupportData(support);const url=displaySupportUrl(meta?.supportUrl);
        return <tr key={transaction.id}><td><strong>{transaction.description}</strong><small>{transaction.reference} · {dateLabel(transaction.date,true)} · {kindLabels[transaction.kind]}</small></td><td>{transactionAccountNames(state,transaction)}<small>{transaction.party}</small></td><td>{meta?.categoryName||transaction.category||'Sin clasificar'}<small>{meta?.groupName||'Sin grupo registrado'}</small>{pending&&<Badge tone="orange">{pending.status==='pending_institutional'?'Clasificación en autorización':'Por legalizar'}</Badge>}</td><td className="cash-money">{formatCOP(transaction.amount)}</td><td><Badge tone={transaction.status==='pending'?'orange':transaction.status==='rejected'||transaction.reversedBy?'red':'green'}>{transaction.reversedBy?'Reversado':transaction.status==='pending'?'Por aprobar':transaction.status==='rejected'?'Rechazado':'Registrado'}</Badge>{receipt&&<small className={receipt.status==='difference'?'cash-negative':'cash-positive'}>{receipt.status==='difference'?`Recepción con diferencia: ${formatCOP(receipt.difference)}`:'Recepción confirmada'}</small>}</td><td><div className="cash-row-actions">{fileUrl&&support?<a className="cash-pill-link" href={fileUrl} download={support.name}><Paperclip size={13}/><span>{support.name}</span></a>:url?<a className="cash-pill-link" href={url} target="_blank" rel="noopener noreferrer"><Link2 size={13}/><span>Ver comprobante</span><ExternalLink size={11}/></a>:<span className="cash-muted">Sin comprobante</span>}<button className="cash-text-button" onClick={()=>onDialog({kind:pending?'legalize':'support',transactionId:transaction.id})}>{canWrite(actor)?'Completar ficha':'Ver ficha'}<ChevronRight size={13}/></button>{canWrite(actor)&&transaction.status==='posted'&&!transaction.reversalOf&&!transaction.reversedBy&&<button className="cash-text-button" onClick={()=>onDialog({kind:'correct',transactionId:transaction.id})}>Solicitar corrección</button>}{canWrite(actor)&&transaction.kind==='transfer'&&transaction.status==='posted'&&!transaction.reversedBy&&!receipt&&<button className="button button-secondary" onClick={()=>onDialog({kind:'receipt',transactionId:transaction.id})}><CheckCheck size={14}/>Confirmar recibido</button>}</div></td></tr>;
      })}</tbody></table></div></section>:<CashEmpty title="No hay movimientos en este período" description="Ajusta las fechas o registra una operación. Las entradas, salidas y traslados conservarán su clasificación, responsable y evidencia." action={canWrite(actor)?<button className="button button-primary" onClick={()=>onDialog({kind:'movement'})}><Plus size={15}/>Registrar movimiento</button>:undefined}/>}
    </>}
    {requests.length>0&&<section className="cash-card"><div className="cash-card-header"><div><h3>Solicitudes de corrección y clasificación</h3><p>Son peticiones conservadas, todavía sin efecto sobre el libro ni los informes definitivos.</p></div><Badge tone="orange">Pendientes de autorización</Badge></div><div className="cash-card-body cash-history-list">{requests.map(request=><article className="cash-history-event" key={request.id}><div><strong>{state.transactions.find(transaction=>transaction.id===request.transactionId)?.description??'Movimiento registrado'}</strong><Badge>Sin aplicar</Badge></div><small>{request.requestedByName} · {timestamp(request.createdAt)}</small><p>{request.reason}</p>{request.proposedAmount&&<p>Importe propuesto: {formatCOP(request.proposedAmount)}. El original se conserva.</p>}</article>)}</div></section>}
  </>;
}

function EvidenceFields({support,supportUrl,onSupport,onUrl,onError,onBusy,photoOnly=false}:{support:Support|undefined;supportUrl:string;onSupport:(support:Support|undefined)=>void;onUrl:(url:string)=>void;onError:(message:string)=>void;onBusy:(busy:boolean)=>void;photoOnly?:boolean}) {
  const [busy,setBusy]=useState(false);const generation=useRef(0);
  async function read(file:File|undefined){const current=++generation.current;onError('');onSupport(undefined);setBusy(false);onBusy(false);if(!file)return;
    if(file.size===0){onError('El archivo está vacío. Adjunta un comprobante legible.');return;}
    const accepted=photoOnly?['image/jpeg','image/png','image/webp']:['application/pdf','image/jpeg','image/png','image/webp'];
    if(!accepted.includes(file.type)||file.size>2*1024*1024){onError(photoOnly?'Selecciona una fotografía JPG, PNG o WebP de hasta 2 MB.':'Selecciona un PDF, JPG, PNG o WebP de hasta 2 MB.');return;}
    setBusy(true);onBusy(true);try{const dataUrl=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('No se pudo leer el comprobante.'));reader.readAsDataURL(file);});if(current===generation.current)onSupport({name:file.name,type:file.type,size:file.size,dataUrl});}catch(reason){if(current===generation.current)onError(explanation(reason));}finally{if(current===generation.current){setBusy(false);onBusy(false);}}
  }
  return <div className="cash-form-section"><h3>{photoOnly?'Fotografía del comprobante de retiro':'Comprobante y evidencia'}</h3><div className="form-grid"><Field label={photoOnly?'Adjuntar fotografía':'Adjuntar factura, recibo o fotografía'} full hint="Máximo 2 MB. El archivo se guarda en este navegador; todavía no se carga a la empresa."><span className="cash-upload"><Paperclip size={18}/><input type="file" accept={photoOnly?'image/jpeg,image/png,image/webp':'application/pdf,image/jpeg,image/png,image/webp'} disabled={busy} onChange={event=>void read(event.target.files?.[0])} aria-label={photoOnly?'Adjuntar fotografía del retiro':'Adjuntar comprobante'}/>{support&&<small>{support.name} · {Math.ceil(support.size/1024)} KB</small>}{busy&&<small role="status">Leyendo comprobante…</small>}</span></Field><Field label="O registrar un enlace HTTPS al comprobante" full hint="Usa una referencia autorizada. Un enlace no se considera una descarga ni una verificación automática del documento."><input type="url" value={supportUrl} onChange={event=>onUrl(event.target.value)} placeholder="https://…" maxLength={2000}/></Field></div></div>;
}

function CashMovementModal(props:ViewProps&{accounts:Account[];initialSessionId?:string;onClose:()=>void}) {
  const {state,actor,mutate,accounts,onClose}=props;const cash=getCashState(state);
  const initial=cash.sessions.find(session=>session.id===props.initialSessionId&&session.status==='open');
  const [flow,setFlow]=useState<'out'|'in'|'transfer'>('out');const [accountId,setAccountId]=useState(initial?.accountId??'');const [date,setDate]=useState(initial?.date??todayBogota());const [categoryId,setCategoryId]=useState('');const [temporary,setTemporary]=useState(false);const [destination,setDestination]=useState('');
  const [amount,setAmount]=useState('');const [party,setParty]=useState('');const [description,setDescription]=useState('');const [notes,setNotes]=useState('');const [support,setSupport]=useState<Support>();const [supportUrl,setSupportUrl]=useState('');const [evidenceError,setEvidenceError]=useState('');const [evidenceBusy,setEvidenceBusy]=useState(false);const [error,setError]=useState('');
  const [debtId,setDebtId]=useState('');const [principal,setPrincipal]=useState('');const [interest,setInterest]=useState('');const [insurance,setInsurance]=useState('');const [commission,setCommission]=useState('');const [lateFee,setLateFee]=useState('');const [reference,setReference]=useState('');const [paymentCondition,setPaymentCondition]=useState<'total'|'partial'>('total');const [documentTotal,setDocumentTotal]=useState('');
  const idempotencyKey=useRef(crypto.randomUUID());
  const account=accounts.find(row=>row.id===accountId);const activeSession=cash.sessions.find(session=>session.accountId===accountId&&session.status==='open');const destinationAccount=accounts.find(row=>row.id===destination);
  const selectedExpense=CASH_OUTFLOW_GROUPS.flatMap(group=>group.categories).find(category=>category.id===categoryId);
  const selectedIncome=CASH_INFLOW_CATEGORIES.find(category=>category.id===categoryId);
  const debtPayment=flow==='out'&&!temporary&&selectedExpense?.groupId==='financiacion-fondos';const financing=flow==='in'&&['prestamos','inversiones'].includes(categoryId);
  const needsDestination=flow==='transfer'||selectedExpense?.direction==='transfer'||selectedIncome?.direction==='transfer';
  const photoOnly=needsDestination&&Boolean(account&&account.kind!=='cash'&&destinationAccount?.kind==='cash');
  const commercial=flow==='in'&&['ventas-regulares','abono-trabajos','venta-activos','pago-deudas'].includes(categoryId);
  let exactPayment:string|undefined;try{if(principal.trim()&&interest.trim())exactPayment=add(normalizeAmount(principal),normalizeAmount(interest),...[insurance,commission,lateFee].map(value=>value.trim()?normalizeAmount(value):'0.00'));}catch{/* Required entries will explain the error on submit. */}
  const debts=state.debts.filter(debt=>debt.locationId===account?.locationId&&debt.status==='active');
  function chooseFlow(next:'out'|'in'|'transfer'){setFlow(next);setCategoryId(next==='transfer'?'retiro-entre-cuentas':'');setTemporary(false);setDebtId('');setDestination('');}
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setError('');if(evidenceBusy||evidenceError){setError(evidenceError||'Espera a que termine la lectura del comprobante.');return;}try{
    if(!account)throw new Error('Selecciona la cuenta de la operación.');
    if(account.kind==='cash'&&!activeSession)throw new Error('Esta caja necesita un turno abierto antes de registrar movimientos.');
    const url=safeHttps(supportUrl);
    if(photoOnly&&(!support||!support.type.startsWith('image/')))throw new Error('Adjunta la fotografía del comprobante de retiro. Un enlace por sí solo no permite verificar que sea una fotografía.');
    if(debtPayment&&!debtId)throw new Error('Vincula este pago a una obligación financiera existente.');
    if(financing&&!debtId)throw new Error('Vincula el capital recibido con la obligación registrada en Deudas e inversionistas.');
    if(commercial&&!reference.trim())throw new Error('Registra la referencia del documento o del préstamo cobrado para conservar su trazabilidad.');
    const selectedCategory=temporary?'por-legalizar':categoryId;
    if(!selectedCategory)throw new Error('Selecciona una clasificación concreta.');
    const kind:CashMovementInput['kind']=needsDestination?'transfer':temporary?'advance':debtPayment?'debt_payment':financing?'loan':flow==='in'?'income':'expense';
    const recordedAmount=debtPayment?exactPayment:money(normalizeAmount(amount));
    if(!recordedAmount)throw new Error('Completa capital e intereses; escribe cero si ese componente no fue pagado. Los cargos opcionales en blanco se consideran no aplicables.');
    const conditionNote=commercial&&categoryId!=='pago-deudas'?`Condición de cobro: ${paymentCondition==='total'?'total':'parcial'}.${documentTotal.trim()?` Total del documento: COP ${money(normalizeAmount(documentTotal))}.`:''}`:'';
    const input:CashMovementInput={accountId:account.id,locationId:account.locationId,sessionId:account.kind==='cash'?activeSession?.id:undefined,date,kind,description,party,categoryId:selectedCategory,amount:recordedAmount,idempotencyKey:idempotencyKey.current,notes:[notes,conditionNote].filter(Boolean).join('\n'),support,supportUrl:url,destinationAccountId:needsDestination?destination:undefined,debtId:(debtPayment||financing)?debtId:undefined,principal:debtPayment?money(normalizeAmount(principal)):undefined,interest:debtPayment?money(normalizeAmount(interest)):undefined,insurance:debtPayment&&insurance.trim()?money(normalizeAmount(insurance)):undefined,commission:debtPayment&&commission.trim()?money(normalizeAmount(commission)):undefined,lateFee:debtPayment&&lateFee.trim()?money(normalizeAmount(lateFee)):undefined,externalReferences:reference.trim()?[{module:categoryId==='venta-activos'?'assets':categoryId==='pago-deudas'?'debts':'sales',id:reference.trim(),label:reference.trim()}]:undefined};
    if(mutate(current=>registerCashMovement(current,input,actor),'Operación registrada en el libro local. Las aprobaciones pendientes no modifican saldos.'))onClose();
  }catch(reason){setError(explanation(reason));}}
  return <Modal title="Registrar movimiento de caja" subtitle="Separa ingresos, gastos, financiación y traslados sin duplicar dinero." onClose={onClose} wide><form className="cash-dialog" onSubmit={submit}>
    <div className="cash-radio-row" aria-label="Naturaleza del movimiento">{([{value:'out',label:'Salida',icon:ArrowUpRight},{value:'in',label:'Entrada',icon:ArrowDownLeft},{value:'transfer',label:'Traslado interno',icon:ArrowRightLeft}] as const).map(({value,label,icon:Icon})=><button type="button" key={value} aria-pressed={flow===value} onClick={()=>chooseFlow(value)}><Icon size={17}/>{label}</button>)}</div>
    <div className="form-grid"><Field label={needsDestination?'Cuenta de origen':'Caja, banco o pasarela'}><select required value={accountId} onChange={event=>{const next=accounts.find(row=>row.id===event.target.value);setAccountId(event.target.value);setDestination('');setDebtId('');const session=cash.sessions.find(row=>row.accountId===next?.id&&row.status==='open');if(next?.kind==='cash'&&session)setDate(session.date);else setDate(todayBogota());}}><option value="" disabled>Selecciona una cuenta</option>{accounts.map(row=><option key={row.id} value={row.id}>{row.name} · {accountKindLabels[row.kind]}</option>)}</select></Field><Field label="Fecha efectiva de la operación"><input type="date" required value={date} max={todayBogota()} onChange={event=>setDate(event.target.value)}/></Field>
      {account&&<div className="cash-info full"><Wallet size={17}/><p>{account.kind==='cash'?(activeSession?`Turno abierto del ${dateLabel(activeSession.date)}, responsable ${activeSession.openedByName}.`:'Esta caja no tiene turno abierto. Abre su turno en «Turnos y arqueos» antes de registrar dinero.'):`La operación se registrará directamente en ${account.name}; no se simulará un paso por efectivo.`}</p></div>}
      {flow==='out'&&<Field label="Tratamiento de la salida" full><select value={temporary?'temporary':'definitive'} onChange={event=>{setTemporary(event.target.value==='temporary');setCategoryId('');setDebtId('');}}><option value="definitive">Salida con clasificación definitiva</option><option value="temporary">Anticipo POR LEGALIZAR</option></select></Field>}
      {!temporary&&<Field label="Clasificación aprobada" full><select required value={categoryId} onChange={event=>{setCategoryId(event.target.value);setDebtId('');}}><option value="" disabled>Selecciona grupo y categoría</option>{flow==='in'?CASH_INFLOW_CATEGORIES.map(category=><option value={category.id} disabled={!category.enabled} key={category.id}>{category.name}{category.enabled?'':' · pendiente de definición'}</option>):CASH_OUTFLOW_GROUPS.filter(group=>flow!=='transfer'||group.categories.some(category=>category.direction==='transfer')).map(group=><optgroup label={group.name} key={group.id}>{group.categories.map(category=><option key={category.id} value={category.id}>{category.name}</option>)}</optgroup>)}</select></Field>}
      {temporary&&<div className="cash-warning full"><AlertTriangle size={17}/><p>Este desembolso queda por legalizar. No se convierte automáticamente en un gasto definitivo y puede impedir el cierre. El comprobante y la clasificación se completarán sin registrar una segunda salida de efectivo.</p></div>}
      {needsDestination&&<Field label="Cuenta de destino" full><select required value={destination} onChange={event=>setDestination(event.target.value)}><option value="" disabled>Selecciona una cuenta distinta</option>{accounts.filter(row=>row.id!==accountId&&row.locationId===account?.locationId).map(row=><option value={row.id} key={row.id}>{row.name}</option>)}</select></Field>}
      {(debtPayment||financing)&&<Field label={debtPayment?'Obligación a la que corresponde el pago':'Obligación vinculada al capital recibido'} full hint={debts.length?'El registro conserva la referencia de la obligación.':'Primero registra las condiciones pactadas en Deudas e inversionistas; aquí no se inventan acreedores ni contratos.'}><select required value={debtId} onChange={event=>{setDebtId(event.target.value);const debt=debts.find(row=>row.id===event.target.value);if(debt)setParty(debt.creditor);}}><option value="" disabled>{debts.length?'Selecciona la obligación':'No hay obligaciones registradas para esta sede'}</option>{debts.map(debt=><option key={debt.id} value={debt.id}>{debt.creditor} · {formatCOP(debt.principal)} original</option>)}</select></Field>}
      {debtPayment?<><Field label="Abono a capital · COP"><input required inputMode="decimal" value={principal} onChange={event=>setPrincipal(event.target.value)} pattern="[0-9]+([.,][0-9]{1,2})?" placeholder="Importe realmente pagado"/></Field><Field label="Intereses pagados · COP" hint="Escribe 0 solo si no se pagaron intereses."><input required inputMode="decimal" value={interest} onChange={event=>setInterest(event.target.value)} pattern="[0-9]+([.,][0-9]{1,2})?" placeholder="Importe realmente pagado"/></Field><Field label="Seguros pagados · COP" hint="Opcional: déjalo en blanco si no aplica."><input inputMode="decimal" value={insurance} onChange={event=>setInsurance(event.target.value)} pattern="[0-9]+([.,][0-9]{1,2})?" placeholder="Opcional, si aplica"/></Field><Field label="Comisiones pagadas · COP" hint="Opcional: déjalo en blanco si no aplica."><input inputMode="decimal" value={commission} onChange={event=>setCommission(event.target.value)} pattern="[0-9]+([.,][0-9]{1,2})?" placeholder="Opcional, si aplica"/></Field><Field label="Mora pagada · COP" hint="Opcional: déjalo en blanco si no aplica. Un cargo de mora requiere comprobante y justificación."><input inputMode="decimal" value={lateFee} onChange={event=>setLateFee(event.target.value)} pattern="[0-9]+([.,][0-9]{1,2})?" placeholder="Opcional, si hubo mora"/></Field><Field label="Total del pago calculado"><input readOnly value={exactPayment?formatCOP(exactPayment):'Falta completar el reparto'}/></Field></>:<Field label="Importe recibido o pagado · COP" full><input required inputMode="decimal" value={amount} onChange={event=>setAmount(event.target.value)} pattern="[0-9]+([.,][0-9]{1,2})?" placeholder="Sin separadores de miles"/></Field>}
      <Field label={flow==='in'?'Nombre del pagador o responsable':'Nombre del beneficiario o responsable'}><input required minLength={2} maxLength={180} value={party} onChange={event=>setParty(event.target.value)} placeholder="Persona o entidad de la operación"/></Field><Field label="Concepto del movimiento"><input required minLength={3} maxLength={180} value={description} onChange={event=>setDescription(event.target.value)} placeholder="¿A qué corresponde?"/></Field>
      {commercial&&<Field label={categoryId==='pago-deudas'?'Referencia del préstamo otorgado que se cobra':categoryId==='venta-activos'?'Documento de venta y referencia del activo':'Referencia de factura, remisión o trabajo'} full hint="Es un vínculo documental local; no confirma ni crea un documento en otro módulo."><input required maxLength={200} value={reference} onChange={event=>setReference(event.target.value)} placeholder="Referencia verificable del documento"/></Field>}
      {commercial&&categoryId!=='pago-deudas'&&<><Field label="Condición del cobro"><select value={paymentCondition} onChange={event=>setPaymentCondition(event.target.value as 'total'|'partial')}><option value="total">Cobro total</option><option value="partial">Cobro parcial / abono</option></select></Field><Field label="Total del documento · COP" hint="No se registra de nuevo como dinero recibido."><input required={paymentCondition==='partial'} inputMode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" value={documentTotal} onChange={event=>setDocumentTotal(event.target.value)} placeholder="Importe del documento, si aplica"/></Field></>}
      <Field label="Observaciones y motivo" full><textarea required={needsDestination} minLength={needsDestination?5:undefined} maxLength={2000} rows={3} value={notes} onChange={event=>setNotes(event.target.value)} placeholder={needsDestination?'Explica el traslado y el uso previsto del dinero…':'Referencia, detalle y condiciones de esta operación…'}/></Field>
    </div>
    <EvidenceFields support={support} supportUrl={supportUrl} onSupport={setSupport} onUrl={setSupportUrl} onError={setEvidenceError} onBusy={setEvidenceBusy} photoOnly={photoOnly}/>
    {needsDestination&&<div className="cash-info"><ArrowRightLeft size={17}/><p>Se crearán extremos compensados de igual valor y fecha. El traslado no será un ingreso ni un gasto externo. La recepción real debe confirmarse por separado; cualquier diferencia conserva una novedad y bloquea el cierre.</p></div>}
    <div className="cash-info"><ShieldCheck size={17}/><p>Las operaciones sensibles o desde $ 5.000.000 quedan pendientes de revisión independiente. El perfil local no puede autorizar su propia solicitud ni representar a otra persona.</p></div>
    {(error||evidenceError)&&<p className="form-error" role="alert">{error||evidenceError}</p>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Cancelar</button><button type="submit" className="button button-primary" disabled={!accountId||Boolean(account?.kind==='cash'&&!activeSession)||Boolean((debtPayment||financing)&&!debtId)||Boolean(evidenceError)||evidenceBusy}><Plus size={16}/>{evidenceBusy?'Leyendo comprobante…':'Registrar en el libro local'}</button></div>
  </form></Modal>;
}

export function MovementEvidenceModal({state,actor,mutate,transaction,mode,onClose}:ViewProps&{transaction:Transaction;mode:'support'|'legalize'|'correct';onClose:()=>void}) {
  const [support,setSupport]=useState<Support>();const [supportUrl,setSupportUrl]=useState('');const [reason,setReason]=useState('');const [categoryId,setCategoryId]=useState('');const [description,setDescription]=useState('');const [party,setParty]=useState('');const [amount,setAmount]=useState('');const [error,setError]=useState('');const [evidenceError,setEvidenceError]=useState('');const [evidenceBusy,setEvidenceBusy]=useState(false);
  const meta=getCashTransactionMetadata(state,transaction.id);const currentSupport=meta?.support??transaction.support;const currentDataUrl=displaySupportData(currentSupport);const currentUrl=displaySupportUrl(meta?.supportUrl);const write=canWrite(actor);
  const preservedEvidence=[...(transaction.support?[{id:'original',support:transaction.support,supportUrl:undefined,actorId:transaction.requestedBy,createdAt:transaction.createdAt}]:[]),...(meta.attachments??[])];
  const photoOnly=transaction.kind==='transfer'&&accountDestination(state,transaction)?.kind==='cash'&&sourceAccount(state,transaction)?.kind!=='cash'&&![currentSupport,...preservedEvidence.map(row=>row.support)].some(support=>support?.type.startsWith('image/')&&Boolean(displaySupportData(support)));
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setError('');try{
    if(evidenceBusy||evidenceError)throw new Error(evidenceError||'Espera a que termine la lectura del comprobante.');const url=safeHttps(supportUrl);
    if(mode==='support'&&!support&&!url)throw new Error('Selecciona el archivo o registra un enlace HTTPS autorizado al comprobante.');
    if(mode==='support'&&photoOnly&&!currentSupport?.type.startsWith('image/')&&!support?.type.startsWith('image/'))throw new Error('Este retiro requiere una fotografía del comprobante. Un enlace o PDF por sí solo no la verifica.');
    const saved=mode==='support'?mutate(current=>attachCashSupport(current,{transactionId:transaction.id,support,supportUrl:url,notes:reason},actor),'Comprobante anexado sin cambiar el importe ni el asiento original.'):mode==='legalize'?mutate(current=>legalizeAdvance(current,{transactionId:transaction.id,categoryId,reason,support,supportUrl:url},actor),'Legalización documentada y clasificación solicitada. Sigue pendiente de autorización institucional.'):mutate(current=>requestCashAmendment(current,{transactionId:transaction.id,kind:'correction',reason,proposedCategoryId:categoryId||undefined,proposedDescription:description.trim()||undefined,proposedParty:party.trim()||undefined,proposedAmount:amount.trim()?money(normalizeAmount(amount)):undefined,support,supportUrl:url},actor),'Solicitud de corrección conservada. El movimiento original no cambió.');
    if(saved)onClose();
  }catch(reason){setError(explanation(reason));}}
  return <Modal title={mode==='support'?'Completar comprobante':mode==='legalize'?'Documentar y solicitar legalización':'Solicitar corrección autorizada'} subtitle={`${transaction.reference} · ${transaction.description}`} onClose={onClose} wide><form className="cash-dialog" onSubmit={submit}>
    <div className="cash-detail-block"><dl><div><dt>Importe original conservado</dt><dd>{formatCOP(transaction.amount)}</dd></div><div><dt>Fecha real de la operación</dt><dd>{dateLabel(transaction.date)}</dd></div><div><dt>Tercero original</dt><dd>{transaction.party}</dd></div><div><dt>Clasificación registrada</dt><dd>{meta?.categoryName||transaction.category||'Sin clasificación'}</dd></div><div><dt>Cuenta</dt><dd>{transactionAccountNames(state,transaction)}</dd></div><div><dt>Comprobante actual</dt><dd>{currentDataUrl&&currentSupport?<a href={currentDataUrl} download={currentSupport.name} className="cash-text-button"><Paperclip size={14}/>{currentSupport.name}</a>:currentUrl?<a href={currentUrl} className="cash-text-button" target="_blank" rel="noopener noreferrer">Abrir comprobante <ExternalLink size={13}/></a>:'Todavía no hay un comprobante asociado'}</dd></div></dl></div>
    {mode!=='support'&&<div className="cash-warning"><LockKeyhole size={18}/><p>{mode==='legalize'?'La categoría POR LEGALIZAR no se convierte en un gasto definitivo sin revisión. Se conservarán el desembolso y la petición de clasificación, sin registrar una segunda salida.':'Esta pantalla registra una propuesta y conserva valores anteriores. No modifica importes, cuentas ni períodos cerrados.'}<br/>La decisión está reservada a Creador o Gerente con autorización institucional. Aquí no se simulan sus códigos ni sus identidades.</p></div>}
    {write?<>
      {mode!=='support'&&<div className="form-grid"><Field label={mode==='legalize'?'Clasificación definitiva propuesta':'Nueva clasificación propuesta (opcional)'} full><select value={categoryId} required={mode==='legalize'} onChange={event=>setCategoryId(event.target.value)}><option value="">{mode==='legalize'?'Selecciona una categoría concreta':'Conservar la clasificación actual'}</option>{CASH_OUTFLOW_GROUPS.filter(group=>group.categories.some(category=>category.direction!=='transfer')).map(group=><optgroup label={group.name} key={group.id}>{group.categories.filter(category=>category.direction!=='transfer').map(category=><option key={category.id} value={category.id}>{category.name}</option>)}</optgroup>)}{mode==='correct'&&<optgroup label="Entradas">{CASH_INFLOW_CATEGORIES.filter(category=>category.enabled&&category.direction==='income').map(category=><option key={category.id} value={category.id}>{category.name}</option>)}</optgroup>}</select></Field>
        {mode==='correct'&&<><Field label="Nuevo concepto propuesto" full><input maxLength={180} value={description} onChange={event=>setDescription(event.target.value)} placeholder="Déjalo vacío para conservar el actual"/></Field><Field label="Nuevo beneficiario o responsable propuesto"><input maxLength={180} value={party} onChange={event=>setParty(event.target.value)} placeholder="Sin cambio, si queda vacío"/></Field><Field label="Nuevo importe propuesto · COP" hint="Proponer un importe no lo aplica. Su corrección financiera exigirá revisión y el asiento correspondiente."><input inputMode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" value={amount} onChange={event=>setAmount(event.target.value)} placeholder="Sin cambio, si queda vacío"/></Field></>}
      </div>}
      <Field label={mode==='support'?'Observaciones sobre el comprobante':'Motivo y evidencia de la solicitud'} full hint={mode==='support'?'La evidencia se asocia mediante un nuevo evento; el movimiento original se conserva.':'Explica la diferencia, el valor correcto y dónde se puede comprobar.'}><textarea required={mode!=='support'} minLength={mode!=='support'?8:undefined} maxLength={2000} rows={3} value={reason} onChange={event=>setReason(event.target.value)} placeholder={mode==='support'?'Referencia de factura, fecha de recepción y observaciones…':'Describe por qué se solicita la corrección o legalización…'}/></Field>
      <EvidenceFields support={support} supportUrl={supportUrl} onSupport={setSupport} onUrl={setSupportUrl} onError={setEvidenceError} onBusy={setEvidenceBusy} photoOnly={photoOnly}/>
    </>:<div className="cash-info"><ShieldCheck size={17}/><p>Tu perfil permite consultar la evidencia, sin anexar documentos ni solicitar cambios.</p></div>}
    {preservedEvidence.length>0&&<section className="cash-form-section"><h3>Comprobantes conservados</h3><p>Cada anexo conserva su archivo o enlace, responsable y fecha.</p><div className="cash-history-list">{preservedEvidence.map((attachment,index)=>{const fileUrl=displaySupportData(attachment.support);const url=displaySupportUrl(attachment.supportUrl);return <article className="cash-history-event" key={attachment.id}><div><strong>{attachment.support?.name||'Comprobante enlazado'}</strong>{fileUrl&&attachment.support?<a className="cash-pill-link" href={fileUrl} download={attachment.support.name}><Paperclip size={13}/>Descargar archivo</a>:url?<a className="cash-pill-link" href={url} target="_blank" rel="noopener noreferrer"><ExternalLink size={13}/>Abrir enlace autorizado</a>:<Badge>Archivo no disponible</Badge>}</div><small>{state.members.find(member=>member.id===attachment.actorId)?.name??'Usuario registrado'} · {timestamp(attachment.createdAt)} · {index===0&&attachment.id==='original'?'Soporte original':'Anexo conservado'}</small></article>;})}</div></section>}
    {meta?.history&&meta.history.length>0&&<section className="cash-form-section"><h3>Historial de la ficha</h3><div className="cash-history-list">{meta.history.map(event=><article className="cash-history-event" key={event.id}><strong>{event.action==='support_attached'?'Comprobante anexado':'Movimiento registrado'}</strong><small>{event.actorName} · {timestamp(event.createdAt)}</small>{event.notes&&<p>{event.notes}</p>}</article>)}</div></section>}
    {(error||evidenceError)&&<p className="form-error" role="alert">{error||evidenceError}</p>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>{write?'Cancelar':'Cerrar ficha'}</button>{write&&<button className="button button-primary" type="submit" disabled={Boolean(evidenceError)||evidenceBusy}>{evidenceBusy?'Leyendo comprobante…':mode==='support'?<><Paperclip size={16}/>Anexar comprobante</>:<><ShieldCheck size={16}/>Guardar solicitud pendiente</>}</button>}</div>
  </form></Modal>;
}

function TransferReceiptModal({state,actor,mutate,transaction,onClose}:ViewProps&{transaction:Transaction;onClose:()=>void}) {
  const [amount,setAmount]=useState('');const [date,setDate]=useState(transaction.date);const [notes,setNotes]=useState('');const [support,setSupport]=useState<Support>();const [supportUrl,setSupportUrl]=useState('');const [error,setError]=useState('');const [evidenceError,setEvidenceError]=useState('');const [evidenceBusy,setEvidenceBusy]=useState(false);
  const source=sourceAccount(state,transaction);const destination=accountDestination(state,transaction);
  let difference:string|null=null;try{if(amount.trim())difference=sub(normalizeAmount(amount),transaction.amount);}catch{/* Actual received value remains absent until valid. */}
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setError('');try{if(evidenceBusy||evidenceError)throw new Error(evidenceError||'Espera a que termine la lectura del comprobante.');if(!amount.trim())throw new Error('Registra el importe efectivamente recibido. No se asume que sea igual al retirado.');if(mutate(current=>recordCashTransferReceipt(current,{transactionId:transaction.id,date,receivedAmount:money(normalizeAmount(amount)),support,supportUrl:safeHttps(supportUrl),notes},actor),'Recepción documentada. Una diferencia conserva su novedad y bloquea el cierre de las cuentas implicadas.'))onClose();}catch(reason){setError(explanation(reason));}}
  return <Modal title="Confirmar recepción del traslado" subtitle={`${source?.name??'Cuenta de origen'} → ${destination?.name??'Cuenta de destino'}`} onClose={onClose}><form className="cash-dialog" onSubmit={submit}>
    <div className="cash-info"><ArrowRightLeft size={18}/><p>Registra lo efectivamente recibido. La confirmación no registra otra entrada ni cambia los extremos originales del traslado.</p></div>
    <div className="form-grid"><Field label="Importe retirado o enviado"><input readOnly value={formatCOP(transaction.amount)}/></Field><Field label="Fecha del envío"><input readOnly type="date" value={transaction.date}/></Field><Field label="Importe efectivamente recibido · COP"><input required inputMode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" value={amount} onChange={event=>setAmount(event.target.value)} placeholder="Sin suponer el importe"/></Field><Field label="Fecha efectiva de recepción"><input required type="date" min={transaction.date} max={todayBogota()} value={date} onChange={event=>setDate(event.target.value)}/></Field><Field label="Diferencia entre recibido y enviado" full><input readOnly value={difference===null?'Falta confirmar el importe':formatCOP(difference)}/></Field><Field label="Responsable y observaciones de recepción" full><textarea required minLength={5} maxLength={2000} rows={3} value={notes} onChange={event=>setNotes(event.target.value)} placeholder="Describe la entrega y cualquier diferencia que deba investigarse…"/></Field></div>
    {difference!==null&&toCents(difference)!==0n&&<div className="cash-warning"><AlertTriangle size={18}/><p>La diferencia quedará abierta y bloqueará el cierre de las cuentas implicadas. No se forzarán importes ni se creará un ajuste automático para ocultarla.</p></div>}
    <EvidenceFields support={support} supportUrl={supportUrl} onSupport={setSupport} onUrl={setSupportUrl} onError={setEvidenceError} onBusy={setEvidenceBusy}/>
    {(error||evidenceError)&&<p className="form-error" role="alert">{error||evidenceError}</p>}<div className="modal-actions"><button className="button button-secondary" type="button" onClick={onClose}>Cancelar</button><button className="button button-primary" type="submit" disabled={Boolean(evidenceError)||evidenceBusy}><CheckCheck size={16}/>{evidenceBusy?'Leyendo comprobante…':'Conservar recepción real'}</button></div>
  </form></Modal>;
}

function CashMonth(props:ViewProps&{onCloseMonth:(month:string)=>void}) {
  const {state,actor,location,onCloseMonth}=props;
  const [month,setMonth]=useState(todayBogota().slice(0,7));
  const cash=getCashState(state);
  const checklist=useMemo(()=>{try{return /^\d{4}-(0[1-9]|1[0-2])$/.test(month)?cashMonthChecklist(state,month):null;}catch{return null;}},[state,month]);
  const closures=cash.monthClosures.filter(closure=>closure.month===month).sort((a,b)=>b.version-a.version);
  const pending=checklist?.items.filter(item=>item.blocking)??[];
  return <>
    <div className="cash-toolbar"><div><h2>Cierre de mes, con evidencia conservada</h2><p>El corte usa el mes calendario completo. Las legalizaciones, diferencias y turnos abiertos se revisan antes de cerrar.</p></div><div className="cash-filters"><label>Mes de revisión<input type="month" required value={month} max={todayBogota().slice(0,7)} onChange={event=>setMonth(event.target.value)}/></label></div></div>
    {location!=='all'&&<div className="cash-info"><Landmark size={17}/><p>El cierre mensual revisa todas las sedes y cuentas de Trefil Electric; el filtro de sede no oculta bloqueos de la empresa.</p></div>}
    {checklist?<>
      <div className="cash-summary"><Metric title="Saldo inicial del mes" value={formatCOP(checklist.report.openingAvailable)} note={monthName(month)}/><Metric title="Disponibilidad al corte" value={formatCOP(checklist.report.closingAvailable)} note="Suma de los saldos individuales" featured/><Metric title="Controles que bloquean" value={String(pending.length)} note="Deben resolverse antes del cierre ordinario"/><Metric title="Versiones conservadas" value={String(closures.length)} note="Informes locales, sin sobrescribir el historial"/></div>
      <div className="cash-close-layout"><section className="cash-card"><div className="cash-card-header"><div><h3>Revisión de {monthName(month)}</h3><p>Los controles se recalculan desde el libro; no sustituyen una comprobación institucional.</p></div><Badge tone={checklist.canClose?'green':'orange'}>{checklist.canClose?'Revisión sin bloqueos':'Requiere atención'}</Badge></div><ul className="cash-checklist">{checklist.items.length?checklist.items.map(item=><li key={item.id}>{item.blocking?<AlertTriangle className="cash-check-blocked" size={18}/>:<Check className="cash-check-ok" size={18}/>}<span><strong>{item.label}</strong>{item.amount!==undefined&&<small>Importe asociado: {formatCOP(item.amount)}</small>}</span><Badge tone={item.blocking?'orange':'green'}>{item.blocking?'Pendiente':'Comprobado'}</Badge></li>):<li><Check size={18} className="cash-check-ok"/><span><strong>No se detectaron novedades en este período.</strong><small>La aprobación definitiva de los informes empresariales requiere una identidad institucional autorizada.</small></span></li>}</ul></section>
        <section className="cash-card"><div className="cash-month-status"><Badge tone={closures.length?'blue':checklist.canClose?'green':'orange'}>{closures.length?'Versión local conservada':checklist.canClose?'Preparado para cierre local':'Cierre ordinario bloqueado'}</Badge><h3>{closures.length?`${closures.length} ${closures.length===1?'versión guardada':'versiones guardadas'}`:checklist.canClose?'Conserva el corte del período':'Primero resuelve las novedades'}</h3><p>El cierre conserva una versión del informe y la relación de movimientos. No elimina diferencias, no cambia fechas ni reemplaza una aprobación empresarial.</p>{canWrite(actor)&&<button className="button button-primary" disabled={!checklist.canClose} onClick={()=>onCloseMonth(month)}><LockKeyhole size={16}/>Revisar y guardar cierre local</button>}<div className="cash-info"><ShieldCheck size={17}/><p>Las correcciones de un período cerrado requieren una petición autorizada. Los registros originales y las versiones anteriores se conservan.</p></div></div></section>
      </div>
      {closures.length>0&&<section className="cash-card"><div className="cash-card-header"><div><h3>Versiones del cierre conservadas</h3><p>Un informe local guardado no se presenta como aprobado por la empresa.</p></div></div><div className="cash-table-wrap"><table className="cash-table"><thead><tr><th>Mes y versión</th><th>Persona responsable</th><th>Fecha de conservación</th><th>Disponibilidad al cierre</th><th>Observaciones</th></tr></thead><tbody>{closures.map(closure=><tr key={closure.id}><td><strong>{monthName(closure.month)}</strong><small>Versión {closure.version} · Cierre local</small></td><td>{closure.closedByName}</td><td>{timestamp(closure.closedAt)}</td><td className="cash-money">{formatCOP(closure.report.closingAvailable)}</td><td>{closure.notes||'Sin observaciones adicionales'}</td></tr>)}</tbody></table></div></section>}
    </>:<CashEmpty title="Selecciona un mes válido" description="La revisión usa fechas de inicio y fin del mes calendario completo. Un período ausente no se interpreta como cero."/>}
  </>;
}

function MonthCloseModal({state,actor,mutate,month,onClose}:ViewProps&{month:string;onClose:()=>void}) {
  const [notes,setNotes]=useState('');const [error,setError]=useState('');const checklist=cashMonthChecklist(state,month);
  function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setError('');try{if(mutate(current=>closeCashMonth(current,{month,notes},actor),'Cierre local conservado con su versión. No se declaró una aprobación institucional.'))onClose();}catch(reason){setError(explanation(reason));}}
  return <Modal title={`Conservar cierre de ${monthName(month)}`} subtitle="Se recalcularán los controles antes de guardar la versión local." onClose={onClose}><form className="cash-dialog" onSubmit={submit}>
    <div className="cash-detail-block"><dl><div><dt>Saldo inicial</dt><dd>{formatCOP(checklist.report.openingAvailable)}</dd></div><div><dt>Disponible al cierre</dt><dd>{formatCOP(checklist.report.closingAvailable)}</dd></div><div><dt>Responsable local</dt><dd>{actor.name}</dd></div><div><dt>Controles pendientes</dt><dd>{checklist.items.filter(item=>item.blocking).length}</dd></div></dl></div>
    <Field label="Observaciones y referencia de la revisión" full><textarea required minLength={8} maxLength={2000} rows={4} value={notes} onChange={event=>setNotes(event.target.value)} placeholder="Identifica los arqueos, conciliaciones y documentos revisados…"/></Field><label className="cash-checkbox"><input type="checkbox" required/>Confirmo que revisé los controles de este período. Entiendo que este cierre es local y no sustituye la autorización institucional del informe.</label>
    {!checklist.canClose&&<p className="form-error" role="alert">Todavía existen controles que bloquean el cierre ordinario.</p>}{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button className="button button-secondary" type="button" onClick={onClose}>Cancelar</button><button className="button button-primary" type="submit" disabled={!checklist.canClose}>Guardar versión del cierre local</button></div>
  </form></Modal>;
}
